import * as THREE from 'three';

/**
 * Service to load and manage high-precision mission trajectory data.
 * Data is loaded from binary files generated by scripts/process-trajectories.js.
 */
const cache: Record<string, Float64Array> = {};
const loading: { [key: string]: Promise<Float64Array | null> | undefined } = {};

/**
 * Service to load and manage high-precision mission trajectory data.
 * Data is loaded from binary files generated by scripts/process-trajectories.js.
 */
export const TrajectoryLoader = {
  /**
   * Load trajectory data for a mission.
   * @param missionId The ID of the mission (e.g., 'voyager1')
   */
  async load(missionId: string): Promise<Float64Array | null> {
    if (cache[missionId]) {
      return cache[missionId];
    }

    if (loading[missionId]) {
      return loading[missionId];
    }

    const loadPromise = (async () => {
      try {
        const response = await fetch(`data/missions/binary/${missionId}.bin?v=${Date.now()}`);
        if (!response.ok) {
          console.warn(`Failed to load trajectory for ${missionId}: ${response.statusText}`);
          return null;
        }

        const buffer = await response.arrayBuffer();
        const data = new Float64Array(buffer);
        cache[missionId] = data;
        return data;
      } catch (e) {
        console.error(`Error loading trajectory for ${missionId}:`, e);
        return null;
      } finally {
        delete loading[missionId];
      }
    })();

    loading[missionId] = loadPromise;
    return loadPromise;
  },

  /**
   * Get the interpolated position at a specific time.
   * @param missionId Mission ID
   * @param date Date timestamp (ms)
   * @returns THREE.Vector3 | null
   */
  getPositionAtTime(missionId: string, date: number): THREE.Vector3 | null {
    const data = cache[missionId];
    if (!data) return null;

    // Detect Stride based on data length validity or metadata
    // We assume 7 if divisible by 7 (and > 0), else 4.
    // Ideally we should store metadata, but auto-detection is okay for this transition.
    let stride = 4;
    if (data.length > 0 && data.length % 7 === 0) {
      stride = 7;
    }

    const count = data.length / stride;

    // Bounds check
    if (count === 0) return null;
    // Check for native JD units
    // J2000 is ~2.45e6. Unix Ms is ~1.7e12.
    // If t0 < 1e9, assume JD buffer.
    const isJD = data.length > 0 && data[0] < 1e9;

    // If data is JD, we must convert request 'date' (Ms) to JD (Days).
    // Conversion: JD = (Ms / 86400000.0) + 2440587.5
    const searchDate = isJD ? date / 86400000.0 + 2440587.5 : date;

    const startTime = data[0];
    const endTime = data[(count - 1) * stride];

    if (searchDate < startTime || searchDate > endTime) return null;

    let low = 0;
    let high = count - 1;
    let index = -1;

    while (low <= high) {
      const mid = Math.floor((low + high) / 2);
      const midTime = data[mid * stride];

      if (midTime === searchDate) {
        index = mid;
        break;
      } else if (midTime < searchDate) {
        // Look in upper half, but keep track of 'mid' as potential lower bound
        index = mid;
        low = mid + 1;
      } else {
        high = mid - 1;
      }
    }

    if (index === -1 || index >= count - 1) return null;

    const t1 = data[index * stride];
    const i1 = index * stride;
    const t2 = data[(index + 1) * stride];
    const i2 = (index + 1) * stride;

    const total = t2 - t1;
    if (total <= 0) return new THREE.Vector3(data[i1 + 1], data[i1 + 2], data[i1 + 3]);

    const alpha = (searchDate - t1) / total; // 0..1

    // Extract Position 1
    const p1x = data[i1 + 1];
    const p1y = data[i1 + 2];
    const p1z = data[i1 + 3];

    // Extract Position 2
    const p2x = data[i2 + 1];
    const p2y = data[i2 + 2];
    const p2z = data[i2 + 3];

    if (stride === 7) {
      // Hermite Cubic Spline
      // Data: [Time, X, Y, Z, VX, VY, VZ]
      // Velocities are AU/Day.

      let T_days: number;
      if (isJD) {
        // Time is already Days.
        T_days = total;
      } else {
        // Time is Ms. Need Days for Velocity scale.
        T_days = total / 86400000;
      }

      const v1x = data[i1 + 4];
      const v1y = data[i1 + 5];
      const v1z = data[i1 + 6];

      const v2x = data[i2 + 4];
      const v2y = data[i2 + 5];
      const v2z = data[i2 + 6];

      // Hermite Basis
      const s = alpha;
      const s2 = s * s;
      const s3 = s * s * s;

      const h00 = 2 * s3 - 3 * s2 + 1;
      const h10 = s3 - 2 * s2 + s;
      const h01 = -2 * s3 + 3 * s2;
      const h11 = s3 - s2;

      // P(s) = h00*p1 + h10*(v1*T) + h01*p2 + h11*(v2*T)
      const x = h00 * p1x + h10 * v1x * T_days + h01 * p2x + h11 * v2x * T_days;
      const y = h00 * p1y + h10 * v1y * T_days + h01 * p2y + h11 * v2y * T_days;
      const z = h00 * p1z + h10 * v1z * T_days + h01 * p2z + h11 * v2z * T_days;

      return new THREE.Vector3(x, y, z);
    } else {
      // Linear Interpolation (Legacy Stride 4)
      const x = p1x + (p2x - p1x) * alpha;
      const y = p1y + (p2y - p1y) * alpha;
      const z = p1z + (p2z - p1z) * alpha;

      return new THREE.Vector3(x, y, z);
    }
  },

  /**
   * Convert the interleaved Float64Array to a standard array of objects used by legacy systems,
   * or return separate arrays for geometry creation.
   * For LineGeometry, we need a flat array of [x, y, z, x, y, z...].
   */
  getGeometryData(missionId: string): number[] | null {
    const data = cache[missionId];
    if (!data) return null;

    const positions: number[] = [];

    let stride = 4;
    if (data.length > 0 && data.length % 7 === 0) {
      stride = 7;
    }

    const count = data.length / stride;

    for (let i = 0; i < count; i++) {
      positions.push(data[i * stride + 1], data[i * stride + 2], data[i * stride + 3]);
    }

    return positions;
  },

  /**
   * Returns the start and end timestamps for the loaded mission data.
   */
  getDetailedRange(missionId: string): { start: number; end: number } | null {
    const data = cache[missionId];
    if (!data || data.length < 4) return null;

    let stride = 4;
    if (data.length > 0 && data.length % 7 === 0) {
      stride = 7;
    }
    const count = data.length / stride;

    return {
      start: data[0],
      end: data[(count - 1) * stride],
    };
  },
};
